    "prefix": "r9v7",
    "source": "~/BGit/all/film/marketing/ACT3_marketing_Home/act3/rows/row_9_for_microdrama/7",
    "html": "<section class=\"r9v7-row\" id=\"r9v7-microdrama\" aria-labelledby=\"r9v7-title\">\n  <img class=\"r9v7-bgimg\" src=\"/v4/row_9/v/ep01.jpg\" alt=\"\" width=\"1600\" height=\"608\" loading=\"lazy\">\n  <div class=\"r9v7-shade\" aria-hidden=\"true\"></div>\n  <div class=\"r9v7-wrap\">\n    <div class=\"r9v7-copy\">\n      <p class=\"r9v7-eyebrow\">For Micro-Drama</p>\n      <h2 class=\"r9v7-title\" id=\"r9v7-title\">Your series. <span>In their pocket.</span></h2>\n      <p class=\"r9v7-lede\">Micro-drama is watched one thumb at a time, on the bus, in bed, between everything else. ACT 3 makes your story for that screen: vertical 9:16 episodes, the same cast in every one, ready for TikTok and Reels.</p>\n      <p class=\"r9v7-lede\">You bring the love story, the betrayal, the twist in the last five seconds. ACT 3 handles the production labor, so you get your hours back for the writing.</p>\n      <a class=\"r9v7-btn\" href=\"https://app.act3ai.com/signup/\">Make your first episode</a>\n    </div>\n    <figure class=\"r9v7-phone\">\n      <div class=\"r9v7-screen\">\n        <div class=\"r9v7-inner\">\n        <img class=\"r9v7-frame r9v7-f1\" src=\"/v4/row_9/v/walk.jpg\" alt=\"Low Tide, episode 1: Jack and Sally walk the beach with the surfboard\" width=\"720\" height=\"1280\" loading=\"lazy\">\n        <img class=\"r9v7-frame r9v7-f2\" src=\"/v4/row_9/v/ots.jpg\" alt=\"Episode 2: over Jack's shoulder, Sally smiles at him\" width=\"720\" height=\"1280\" loading=\"lazy\">\n        <img class=\"r9v7-frame r9v7-f3\" src=\"/v4/row_9/v/sally_car.jpg\" alt=\"Episode 3: the same Sally in the car at golden hour\" width=\"720\" height=\"1280\" loading=\"lazy\">\n        </div>\n        <span class=\"r9v7-show\">LOW TIDE</span>\n      </div>\n      <figcaption class=\"r9v7-cap\">Frames from three episodes of our sample show, &ldquo;Low Tide&rdquo;. Same Jack, same Sally.</figcaption>\n    </figure>\n  </div>\n</section>",
    "css": ".v4 .r9v7-row { --r9v7-bg: #0b0806; --r9v7-shade: linear-gradient(90deg, rgba(11, 8, 6, 0.96) 0%, rgba(11, 8, 6, 0.86) 42%, rgba(11, 8, 6, 0.45) 75%, rgba(11, 8, 6, 0.7) 100%); --r9v7-text: #fff8f0; --r9v7-body: #e6dccf; --r9v7-accent: #ffb068; --r9v7-btn-bg: #ffb068; --r9v7-btn-text: #2a1402; --r9v7-cap: #d9cdbf; position: relative; overflow: hidden; isolation: isolate; background-color: var(--r9v7-bg); color: var(--r9v7-text); font-family: \"Sora\", system-ui, -apple-system, \"Segoe UI\", sans-serif; padding: clamp(60px, 7vw, 104px) 0; }\n.v4[data-v4-theme=\"light\"] .r9v7-row { --r9v7-bg: #fbf4ea; --r9v7-shade: linear-gradient(90deg, rgba(251, 244, 234, 0.97) 0%, rgba(251, 244, 234, 0.9) 42%, rgba(251, 244, 234, 0.5) 75%, rgba(251, 244, 234, 0.75) 100%); --r9v7-text: #20150b; --r9v7-body: #45372a; --r9v7-accent: #b45a08; --r9v7-btn-bg: #20150b; --r9v7-btn-text: #fff4e6; --r9v7-cap: #4f4133; }\n.v4 .r9v7-row *,\n.v4 .r9v7-row *::before,\n.v4 .r9v7-row *::after { box-sizing: border-box; }\n.v4 .r9v7-bgimg { position: absolute; inset: -40px; width: calc(100% + 80px); height: calc(100% + 80px); object-fit: cover; filter: blur(22px) saturate(1.1); z-index: -2; }\n.v4 .r9v7-shade { position: absolute; inset: 0; background: var(--r9v7-shade); z-index: -1; }\n.v4 .r9v7-wrap { max-width: 1200px; margin: 0 auto; padding: 0 clamp(20px, 4vw, 48px); display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 0.8fr); gap: clamp(32px, 5vw, 80px); align-items: center; }\n.v4 .r9v7-eyebrow { margin: 0 0 14px; font-size: 14px; font-weight: 600; letter-spacing: 0.16em; text-transform: uppercase; color: var(--r9v7-accent); }\n.v4 .r9v7-title { margin: 0 0 22px; font-weight: 700; font-size: clamp(38px, 5vw, 66px); line-height: 1.05; letter-spacing: -0.03em; }\n.v4 .r9v7-title span { display: block; color: var(--r9v7-accent); }\n.v4 .r9v7-lede { margin: 0 0 16px; font-size: clamp(17px, 1.3vw, 19px); line-height: 1.65; color: var(--r9v7-body); max-width: 34em; }\n.v4 .r9v7-btn { display: inline-block; margin-top: 14px; padding: 15px 28px; border-radius: 999px; background: var(--r9v7-btn-bg); color: var(--r9v7-btn-text); font-weight: 600; font-size: 17px; text-decoration: none; }\n.v4 .r9v7-btn:hover { filter: brightness(1.06); }\n.v4 .r9v7-btn:focus-visible { outline: 2px solid var(--r9v7-accent); outline-offset: 4px; }\n.v4 .r9v7-phone { margin: 0 auto; width: min(100%, 290px); }\n.v4 .r9v7-screen { position: relative; aspect-ratio: 9 / 18; border-radius: 40px; padding: 10px; background: #111; box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.22), 0 40px 90px rgba(0, 0, 0, 0.55), 0 0 80px rgba(255, 176, 104, 0.25); overflow: hidden; }\n.v4 .r9v7-inner { position: absolute; inset: 10px; border-radius: 31px; overflow: hidden; background: #000; }\n.v4 .r9v7-frame { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }\n.v4 .r9v7-f2,\n.v4 .r9v7-f3 { opacity: 0; }\n.v4 .r9v7-show { position: absolute; top: 26px; left: 50%; transform: translateX(-50%); padding: 4px 12px; border-radius: 999px; background: rgba(0, 0, 0, 0.55); color: #fff; font-size: 12px; font-weight: 700; letter-spacing: 0.18em; }\n.v4 .r9v7-cap { margin: 16px 0 0; font-size: 15px; line-height: 1.5; text-align: center; color: var(--r9v7-cap); }\n@media (prefers-reduced-motion: no-preference) {\n.v4 .r9v7-f1 { animation: r9v7-a 12s infinite; }\n.v4 .r9v7-f2 { animation: r9v7-b 12s infinite; }\n.v4 .r9v7-f3 { animation: r9v7-c 12s infinite; }\n.v4 .r9v7-frame { transform-origin: 50% 40%; }\n}\n@keyframes r9v7-a { 0%, 28% { opacity: 1; transform: scale(1.06); } 33%, 95% { opacity: 0; transform: scale(1); } 100% { opacity: 1; transform: scale(1.06); } }\n@keyframes r9v7-b { 0%, 28% { opacity: 0; } 33%, 61% { opacity: 1; transform: scale(1.05); } 66%, 100% { opacity: 0; } }\n@keyframes r9v7-c { 0%, 61% { opacity: 0; } 66%, 95% { opacity: 1; transform: scale(1.05); } 100% { opacity: 0; } }\n@media (max-width: 860px) {\n.v4 .r9v7-wrap { grid-template-columns: minmax(0, 1fr); }\n.v4 .r9v7-phone { width: min(78%, 260px); }\n.v4 .r9v7-row { --r9v7-shade: linear-gradient(180deg, rgba(11, 8, 6, 0.93), rgba(11, 8, 6, 0.8)); }\n.v4[data-v4-theme=\"light\"] .r9v7-row { --r9v7-shade: linear-gradient(180deg, rgba(251, 244, 234, 0.95), rgba(251, 244, 234, 0.82)); }\n}",
